package kindergarten

import (
	"errors"
	"fmt"
	"sort"
	"strings"
)

// Garden holds the plants assigned to each child in the class.
type Garden struct {
	rows    [2]string
	plants  map[string][]string
}

var plantNames = map[rune]string{
	'G': "grass",
	'C': "clover",
	'R': "radishes",
	'V': "violets",
}

func NewGarden(diagram string, children []string) (*Garden, error) {
	rows := strings.Split(diagram, "\n")
	if len(rows) != 3 || rows[0] != "" {
		return nil, errors.New("diagram must contain two rows, each preceded by a newline")
	}
	if len(rows[1]) != len(rows[2]) {
		return nil, errors.New("diagram rows must be the same length")
	}
	if len(rows[1])%2 != 0 {
		return nil, errors.New("diagram must contain an even number of cups")
	}
	for _, r := range rows[1] + rows[2] {
		if _, ok := plantNames[r]; !ok {
			return nil, fmt.Errorf("invalid cup code %q", r)
		}
	}

	names := make([]string, len(children))
	copy(names, children)
	sort.Strings(names)
	seen := make(map[string]bool, len(names))
	for _, n := range names {
		if seen[n] {
			return nil, fmt.Errorf("duplicate name %q", n)
		}
		seen[n] = true
	}

	g := &Garden{
		rows:   [2]string{rows[1], rows[2]},
		plants: make(map[string][]string, len(names)),
	}
	for i, name := range names {
		start := 2 * i
		g.plants[name] = []string{
			plantNames[rune(rows[1][start])],
			plantNames[rune(rows[1][start+1])],
			plantNames[rune(rows[2][start])],
			plantNames[rune(rows[2][start+1])],
		}
	}
	return g, nil
}

func (g *Garden) Plants(child string) ([]string, bool) {
	plants, ok := g.plants[child]
	return plants, ok
}
```

