package kindergarten

import (
	"errors"
	"fmt"
	"sort"
	"strings"
)

// plantNames maps each diagram cup code to the plant it represents.
var plantNames = map[rune]string{
	'G': "grass",
	'C': "clover",
	'R': "radishes",
	'V': "violets",
}

// Garden holds the plants assigned to each child in the class.
type Garden struct {
	rows   [2]string
	plants map[string][]string
}

// NewGarden parses the diagram and assigns cups to the children,
// alphabetically by name. The diagram starts each row with a '\n',
// which allows Go's raw string literals to present diagrams in source
// code nicely as two rows flush left, for example,
//
//	diagram := `
//	VVCCGG
//	VVCCGG`
func NewGarden(diagram string, children []string) (*Garden, error) {
	rows := strings.Split(diagram, "\n")
	if len(rows) != 3 || rows[0] != "" {
		return nil, errors.New("diagram must consist of two rows, each preceded by a newline")
	}
	if len(rows[1]) != len(rows[2]) {
		return nil, errors.New("diagram rows must be the same length")
	}
	if len(rows[1])%2 != 0 {
		return nil, errors.New("diagram must contain an even number of cups")
	}
	for _, r := range rows[1] + rows[2] {
		if _, ok := plantNames[r]; !ok {
			return nil, fmt.Errorf("invalid cup code %q", r)
		}
	}

	// Sort a copy so the caller's slice is left untouched.
	names := make([]string, len(children))
	copy(names, children)
	sort.Strings(names)
	for i, name := range names {
		if i > 0 && names[i-1] == name {
			return nil, fmt.Errorf("duplicate name %q", name)
		}
	}

	g := &Garden{
		rows:   [2]string{rows[1], rows[2]},
		plants: make(map[string][]string, len(names)),
	}
	for i, name := range names {
		start := 2 * i
		g.plants[name] = []string{
			plantNames[rune(rows[1][start])],
			plantNames[rune(rows[1][start+1])],
			plantNames[rune(rows[2][start])],
			plantNames[rune(rows[2][start+1])],
		}
	}
	return g, nil
}

// Plants returns the four plants assigned to the named child, in the
// order: first row left, first row right, second row left, second row
// right. The second return value reports whether the child is in the
// garden.
func (g *Garden) Plants(child string) ([]string, bool) {
	plants, ok := g.plants[child]
	return plants, ok
}
